def parse_log_line(line):
    parts = line.split(" ", 3)
    return {"level": parts[2], "message": parts[3]}

def parse_log_line(line):
    parts = line.strip().split(None, 3)
    if len(parts) < 4:
        return None
    return {"level": parts[2].upper(), "message": parts[3]}

